import { Box } from "@/shared/ui/layout/Box";
import { Grid } from "@/shared/ui/layout/Grid";
import { Text } from "@/shared/ui/typography/Text";

export interface Commit {
  s: string;
  m: string;
  who: string;
  t: string;
  head?: boolean;
  merge?: boolean;
}
interface LogViewProps {
  small?: boolean;
  commits?: Commit[];
}
const DEMO_COMMITS: Commit[] = [
  { s: "a1b2c3d", m: "Add live fleet roster endpoint", who: "octocat", t: "2h", head: true },
  { s: "e4f5g6h", m: "Merge feature/export-endpoint", who: "hubot", t: "5h", merge: true },
  { s: "i7j8k9l", m: "Fix credit reservation race", who: "octocat", t: "1d" },
];
export function LogView({ small = false, commits = DEMO_COMMITS }: LogViewProps) {
  return (
    <Box style={{
      flex: 1, minHeight: 0, overflow: "auto",
      padding: small ? "6px 10px" : "10px 14px",
    }}>
      {commits.map((c) => (
        <Grid key={c.s} className="mono" cols="16px 50px 1fr auto" gap={8} align="baseline" style={{
          padding: "4px 0",
          fontSize: small ? 10 : 11,
        }}>
          <Text style={{ color: c.head ? "var(--accent)" : c.merge ? "var(--info)" : "var(--fg-dim)" }}>
            {c.head ? "●" : c.merge ? "◆" : "○"}
          </Text>
          <Text tone="accent">{c.s}</Text>
          <Text style={{
            color: "var(--fg-muted)",
            whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
          }}>
            {c.m} <Text tone="dim">· @{c.who}</Text>
          </Text>
          <Text tone="dim" size={small ? 9 : 9.5}>{c.t}</Text>
        </Grid>
      ))}
    </Box>
  );
}
